      "focusHoldingName": {
        "type": "string",
        "description": "触发下跌提醒的重点持仓名称",
        "sampleValue": "招商白酒"
      },
      "alertText": {
        "type": "string",
        "description": "下跌提醒说明短文案",
        "sampleValue": "已跌破提醒线"
      }
    }
  },
  "assetCandidates": []
}

